CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT );
INSERT OR IGNORE INTO settings(key, value) VALUES ('restaurant_name', 'Mi restaurante');
INSERT OR IGNORE INTO settings(key, value) VALUES ('iva_pct', '10');
INSERT OR IGNORE INTO settings(key, value) VALUES ('food_cost_target', '30');
CREATE TABLE IF NOT EXISTS users ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, username TEXT NOT NULL UNIQUE COLLATE NOCASE, pass TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('direccion','cocina','sala')), is_super INTEGER NOT NULL DEFAULT 0, perms TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS sessions ( token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS suppliers ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, contact TEXT, phone TEXT, email TEXT, cif TEXT, order_days TEXT, notes TEXT, active INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS products ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, category TEXT, unit TEXT NOT NULL DEFAULT 'kg', price REAL NOT NULL DEFAULT 0, supplier_id INTEGER, min_stock REAL NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS price_history ( id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, old_price REAL, new_price REAL, receipt_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS orders ( id INTEGER PRIMARY KEY AUTOINCREMENT, supplier_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'enviado' CHECK (status IN ('borrador','enviado','recibido','cancelado')), order_date TEXT NOT NULL, expected_date TEXT, notes TEXT, user_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS order_lines ( id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, product_id INTEGER NOT NULL, qty REAL NOT NULL, price REAL, input_qty REAL, input_unit TEXT, unit_label TEXT );
CREATE TABLE IF NOT EXISTS receipts ( id INTEGER PRIMARY KEY AUTOINCREMENT, supplier_id INTEGER NOT NULL, order_id INTEGER, delivery_note TEXT, receipt_date TEXT NOT NULL, total REAL NOT NULL DEFAULT 0, notes TEXT, user_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS receipt_lines ( id INTEGER PRIMARY KEY AUTOINCREMENT, receipt_id INTEGER NOT NULL, product_id INTEGER NOT NULL, qty REAL NOT NULL, price REAL NOT NULL, ordered_qty REAL, input_qty REAL, input_unit TEXT, unit_label TEXT, input_price REAL );
CREATE TABLE IF NOT EXISTS movements ( id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, type TEXT NOT NULL CHECK (type IN ('entrada','merma','consumo_personal','venta','ajuste')), qty REAL NOT NULL, unit_cost REAL NOT NULL DEFAULT 0, reason TEXT, notes TEXT, label TEXT, grp TEXT, ref_type TEXT, ref_id INTEGER, user_id INTEGER, mov_date TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS inventories ( id INTEGER PRIMARY KEY AUTOINCREMENT, inv_date TEXT NOT NULL, notes TEXT, total_diff_value REAL, user_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS recipes ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, category TEXT, pvp REAL NOT NULL DEFAULT 0, portions REAL NOT NULL DEFAULT 1, pos_name TEXT, notes TEXT, active INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS recipe_lines ( id INTEGER PRIMARY KEY AUTOINCREMENT, recipe_id INTEGER NOT NULL, product_id INTEGER NOT NULL, qty REAL NOT NULL, waste_pct REAL NOT NULL DEFAULT 0, input_qty REAL, input_unit TEXT );
CREATE TABLE IF NOT EXISTS sales_imports ( id INTEGER PRIMARY KEY AUTOINCREMENT, date_from TEXT NOT NULL, date_to TEXT NOT NULL, filename TEXT, rows INTEGER, revenue REAL, user_id INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS sales ( id INTEGER PRIMARY KEY AUTOINCREMENT, import_id INTEGER NOT NULL, recipe_id INTEGER NOT NULL, sale_date TEXT NOT NULL, units REAL NOT NULL, revenue REAL NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS fixed_costs ( id INTEGER PRIMARY KEY AUTOINCREMENT, concept TEXT NOT NULL, category TEXT, amount REAL NOT NULL DEFAULT 0, frequency TEXT NOT NULL DEFAULT 'mensual' CHECK (frequency IN ('mensual','trimestral','anual')), notes TEXT, active INTEGER NOT NULL DEFAULT 1 );
CREATE INDEX IF NOT EXISTS idx_mov_product ON movements(product_id);
CREATE INDEX IF NOT EXISTS idx_mov_date ON movements(mov_date, type);
CREATE INDEX IF NOT EXISTS idx_mov_grp ON movements(grp);
CREATE INDEX IF NOT EXISTS idx_mov_ref ON movements(ref_type, ref_id);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(sale_date);
CREATE INDEX IF NOT EXISTS idx_receipts_date ON receipts(receipt_date);
CREATE INDEX IF NOT EXISTS idx_rl_recipe ON recipe_lines(recipe_id);
CREATE TABLE IF NOT EXISTS pos_aliases ( id INTEGER PRIMARY KEY AUTOINCREMENT, pos_name TEXT NOT NULL UNIQUE COLLATE NOCASE, recipe_id INTEGER NOT NULL, factor REAL NOT NULL DEFAULT 1, pvp REAL );
CREATE TABLE IF NOT EXISTS pos_pending ( id INTEGER PRIMARY KEY AUTOINCREMENT, pos_name TEXT NOT NULL, units REAL NOT NULL, revenue REAL, date_from TEXT NOT NULL, date_to TEXT NOT NULL, source TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS product_formats ( id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, name TEXT NOT NULL, factor REAL NOT NULL, price REAL, is_default INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, UNIQUE (product_id, name) );
CREATE INDEX IF NOT EXISTS idx_formats_product ON product_formats(product_id);
CREATE TABLE IF NOT EXISTS inventory_lines ( id INTEGER PRIMARY KEY AUTOINCREMENT, inventory_id INTEGER NOT NULL, product_id INTEGER NOT NULL, expected REAL, counted REAL NOT NULL, detail TEXT );
CREATE TABLE IF NOT EXISTS cash_days ( id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL UNIQUE, cash REAL NOT NULL DEFAULT 0, card REAL NOT NULL DEFAULT 0, bizum REAL NOT NULL DEFAULT 0, other REAL NOT NULL DEFAULT 0, cash_out REAL NOT NULL DEFAULT 0, pos_total REAL, covers INTEGER, notes TEXT, user_id INTEGER, updated_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS ocr_scans ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, provider TEXT, supplier_id INTEGER, receipt_id INTEGER, result TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS ocr_aliases ( id INTEGER PRIMARY KEY AUTOINCREMENT, supplier_id INTEGER NOT NULL, source TEXT NOT NULL, product_id INTEGER NOT NULL, unit TEXT, UNIQUE (supplier_id, source) );
